  'useEverywhere.modalAria': '随处使用 Pixflow Design',
  'useEverywhere.modalTitle': '随处使用 Pixflow Design',
  'useEverywhere.modalSubtitle': '把 Pixflow Design 接入任何 IDE、智能体或脚本：CLI、HTTP、MCP 和 Skills。使用“复制智能体指南”，粘贴到 Claude Code、Codex、Cursor、openclaw 或 hermes 中即可完成配置。',
